"""## Resources"""

import numpy as np
import matplotlib.pyplot as plt
from matplotlib.animation import FuncAnimation
from IPython.display import HTML

def create_null_snatch_animation():
    fig, ax = plt.subplots(figsize=(8, 8), facecolor='black')
    ax.set_facecolor('black')

    # Hexagon Grid (The Honeycomb)
    n_hex = 15
    x = np.random.uniform(-10, 10, n_hex)
    y = np.random.uniform(-10, 10, n_hex)
    colors = ['#8A2BE2'] * n_hex # Starting Violet (Light Zone)

    scat = ax.scatter(x, y, s=500, c=colors, edgecolors='white', marker='h', alpha=0.8)
    ax.set_xlim(-12, 12)
    ax.set_ylim(-12, 12)
    ax.axis('off')

    def update(frame):
        # The 'Null' starts pulling everything to (0,0)
        # Frame 0-20: Panic Shiver (Red shift)
        # Frame 20-100: Total Collapse
        strength = max(0, (frame - 20) / 40)

        new_x = x * (1 - strength)
        new_y = y * (1 - strength)

        # Color transition from Violet to Dark Red to Black
        if frame < 20:
            current_colors = ['#8A2BE2'] * n_hex
        elif frame < 50:
            current_colors = ['#FF0000'] * n_hex # Alert Red
        else:
            current_colors = ['#111111'] * n_hex # The Null

        scat.set_offsets(np.c_[new_x, new_y])
        scat.set_facecolor(current_colors)
        scat.set_alpha(max(0, 1 - strength))
        return scat,

    ani = FuncAnimation(fig, update, frames=100, interval=50, blit=True)
    plt.close()
    return HTML(ani.to_jshtml())

# Execute in Colab to see the video!
create_null_snatch_animation()

