import numpy as np
import matplotlib.pyplot as plt
from matplotlib.animation import FuncAnimation
import os

try:
    from google.colab import files
    IN_COLAB = True
except:
    IN_COLAB = False

def render_mp4_null_snatch():
    # Setup the Dark Stage
    fig, ax = plt.subplots(figsize=(10, 10), facecolor='black')
    ax.set_facecolor('black')

    # 1. THE LIGHT ZONE GRID
    n_hex = 50
    x = np.random.uniform(-10, 10, n_hex)
    y = np.random.uniform(-10, 10, n_hex)

    # 2. THE PREDATOR NEEDLES (Hyper-Velocity Sparks)
    n_sparks = 80
    sx = np.random.uniform(-20, 20, n_sparks)
    sy = np.random.uniform(-20, 20, n_sparks)

    # Initialize Plot Elements
    scat = ax.scatter(x, y, s=300, marker='h', edgecolors='white', linewidth=0.7)
    sparks = ax.scatter(sx, sy, s=20, color='white', marker='|', alpha=0)

    ax.set_xlim(-18, 18)
    ax.set_ylim(-18, 18)
    ax.axis('off')

    def animate(frame):
        # STAGE 1: THE COUNTER-ATTACK (0-30)
        if frame < 30:
            p = frame / 30
            sparks.set_offsets(np.c_[sx * (1 - p**2), sy * (1 - p**2)])
            sparks.set_alpha(1)
            scat.set_facecolor('#9400D3') # Deep Violet

        # STAGE 2: THE BREACH DETECTION (30-50)
        elif frame < 50:
            sparks.set_alpha(0)
            # Flickering Red Alert
            color = '#FF0000' if frame % 2 == 0 else '#550000'
            scat.set_facecolor(color)

        # STAGE 3: THE NULL SNATCH (50-120)
        else:
            p = (frame - 50) / 70
            # Exponential collapse to the center
            scat.set_offsets(np.c_[x * (1 - p**1.5), y * (1 - p**1.5)])
            scat.set_alpha(1 - p)
            scat.set_facecolor('#000000')

        return scat, sparks

    ani = FuncAnimation(fig, animate, frames=120, interval=30, blit=True)

    # SAVE AS MP4
    output_file = "omninexus_null_snatch_cinematic.mp4"
    print("Encoding MP4... this may take a moment for high-graphics...")

    # Using 'ffmpeg' writer for MP4 compatibility
    ani.save(output_file, writer='ffmpeg', fps=30, dpi=100,
             extra_args=['-vcodec', 'libx264', '-pix_fmt', 'yuv420p'])

    plt.close()

    if IN_COLAB:
        print(f"Render Complete. Downloading {output_file} now!")
        files.download(output_file)
    else:
        print(f"Saved locally: {os.path.abspath(output_file)}")

# Execute the render
render_mp4_null_snatch()

