import gdspy
import matplotlib.pyplot as plt
from mpl_toolkits.mplot3d import Axes3D
from mpl_toolkits.mplot3d.art3d import Poly3DCollection
import numpy as np

# Load the GDSII library
lib = gdspy.GdsLibrary(infile='infiniminta_omninexus_total.gds')
cell_name = 'INFINIMINTA_OMNINEXUS_TOTAL'
cell = lib.cells[cell_name]

fig = plt.figure(figsize=(12, 10))
ax = fig.add_subplot(111, projection='3d')

layer_colors = {
    1: 'skyblue',  # Light Zone
    2: 'lightgray',  # Grey Zone
    5: 'darkgrey', # Null Zone
    7: 'gold',     # C14 Sensors
    8: 'red',      # Predator Ports
    11: 'purple',   # Bio-photonic Sensors
    12: 'black',    # Scar Geometry
    14: 'lightgreen', # Proximity Sensors
    15: 'orange',    # Predictive RNN Buffer
    16: 'cyan'      # Metabolic Compensator
}

layer_z_offset = {
    1: 0,      # Base layer
    2: 0.5,    # Slightly above Light
    5: -0.5,   # Below Light
    7: 1.0,    # Above Light and Grey
    8: 0.75,   # Predator ports slightly above Grey
    11: 1.2,   # Bio-photonic sensors slightly higher
    12: 0.8,    # Scar geometry slightly above predator ports
    14: 0.2,    # Proximity Sensors, just above base layer
    15: 0.9,     # Predictive RNN Buffer, above most layers
    16: 0.6      # Metabolic Compensator, between Grey and Predator ports
}

all_x = []
all_y = []
all_z = []

# Check if any polygons exist in the cell
if not cell.polygons:
    print(f"[WARNING] Cell '{cell_name}' contains no polygons to plot.")
else:
    print(f"[*] Found {len(cell.polygons)} polygon sets in cell '{cell_name}'.")

# Iterate through all polygons in the cell
for polygon_set in cell.polygons:
    layer = polygon_set.layers[0] # Assuming one layer per polygon set
    color = layer_colors.get(layer, 'green') # Default to green for other layers
    z_offset = layer_z_offset.get(layer, 0)

    for points in polygon_set.polygons:
        # Prepare vertices for Poly3DCollection
        verts = [[(p[0], p[1], z_offset) for p in points]]

        # Create and add Poly3DCollection for filled polygons
        poly3d = Poly3DCollection(verts, facecolors=color, linewidths=0.5, edgecolors='k', alpha=0.3)
        ax.add_collection3d(poly3d)

        # Also draw edges for clarity using ax.plot
        x = [p[0] for p in points]
        y = [p[1] for p in points]
        z = [z_offset] * len(points)

        # Add the first point again to close the polygon in 3D plot
        x.append(x[0])
        y.append(y[0])
        z.append(z[0])
        ax.plot(x, y, z, color=color, alpha=0.8)

        all_x.extend(x)
        all_y.extend(y)
        all_z.extend(z)

ax.set_xlabel('X Dimension (um)')
ax.set_ylabel('Y Dimension (um)')
ax.set_zlabel('Layer Z-Offset (um)')
ax.set_title(f'3D Visualization of {cell_name} GDSII Layout')

# Calculate dynamic limits based on all plotted points
if all_x and all_y and all_z:
    min_x, max_x = min(all_x), max(all_x)
    min_y, max_y = min(all_y), max(all_y)
    min_z, max_z = min(all_z), max(all_z)

    bbox = cell.get_bounding_box()
    if bbox is not None:
        min_x = min(min_x, bbox[0][0])
        max_x = max(max_x, bbox[1][0])
        min_y = min(min_y, bbox[0][1])
        max_y = max(max_y, bbox[1][1])

    range_x = max_x - min_x
    range_y = max_y - min_y
    range_z = max_z - min_z

    # Determine the maximum range across all dimensions to set equal aspect ratio
    max_range = max(range_x, range_y, range_z)

    mid_x = (min_x + max_x) / 2
    mid_y = (min_y + max_y) / 2
    mid_z = (min_z + max_z) / 2

    # Set limits to make the plot appear cubic
    ax.set_xlim(mid_x - max_range / 2, mid_x + max_range / 2)
    ax.set_ylim(mid_y - max_range / 2, mid_y + max_range / 2)
    ax.set_zlim(mid_z - max_range / 2, mid_z + max_range / 2)
else:
    print("[WARNING] No polygon data found to set plot limits or plot was empty.")

plt.show()

import numpy as np

class InfinimintaCore:
    def __init__(self, cube_dim=128):
        """
        Initializes a 3D Photonic Voxel Grid.
        Each voxel in the cube stores data as a specific refractive phase.
        """
        self.dim = cube_dim
        # The 'Infinite' Storage: A 3D grid of refractive index values
        self.storage_grid = np.zeros((self.dim, self.dim, self.dim))
        self.c14_entropy_source = np.random.default_rng(seed=5730) # C14 half-life seed

    def generate_firewall_key(self):
        """Generates a 10MHz shifting hardware key based on C14 decay."""
        return self.c14_entropy_source.random() * 2 * np.pi

    def write_data(self, x, y, z, data_payload, wavelength):
        """
        Indexes data into a 3D voxel.
        Uses wavelength as a 'sub-index' for density.
        """
        # Data is stored as a phase value (0 to 2pi)
        phase_value = (data_payload % 256) / 256.0 * 2 * np.pi
        self.storage_grid[x, y, z] = phase_value + (1.0 / wavelength)
        print(f"[*] Data Indexed at Voxel ({x},{y},{z}) with Wavelength {wavelength}nm")

    def access_request(self, x, y, z, request_phase, is_authorized=False):
        """
        The 10MHz Firewall Logic.
        If the light pulse phase doesn't match the shifting C14 key,
        the 'firewall' pixels shift index to block/absorb the pulse.
        For authorized access, `request_phase` is treated as the correct key.
        """
        if is_authorized:
            # For authorized access, the request_phase is the expected firewall key.
            firewall_key_to_check = request_phase
        else:
            # For unauthorized attempts, generate a new key to simulate current hardware state.
            firewall_key_to_check = self.generate_firewall_key()

        # Check if the incoming light pulse 'fits' the current firewall geometry
        if np.abs(request_phase - firewall_key_to_check) < 0.05:
            print("[✓] ACCESS GRANTED: Light pulse aligned with Firewall geometry.")
            return self.storage_grid[x, y, z]
        else:
            # Physical Block: The 'pixels' shift to a high-absorption index
            print("[X] ATTACK BLOCKED: Phase mismatch. Rerouting to optical black hole.")
            return None

    def get_storage_capacity_bytes(self):
        """
        Calculates the total storage capacity of the Infiniminta Grid in bytes.
        Each voxel stores approximately 1 byte (256 distinct phase values).
        """
        return self.dim**3

# --- EXECUTION ---
chip = InfinimintaCore()

# 1. Store a byte in the 3D grid
# Let's put a 'Terabyte' chunk at a specific 3D coordinate
chip.write_data(x=50, y=25, z=80, data_payload=101, wavelength=1550)

# 2. Attempt to read with a WRONG phase (Simulating a hack)
print("\n--- Unauthorized Access Attempt ---")
chip.access_request(50, 25, 80, request_phase=1.5)

# 3. Attempt to read with the CORRECT phase (Simulating AI management)
print("\n--- Authorized AI Data Fetch ---")
correct_key = chip.generate_firewall_key() # In reality, the AI knows the C14 seed
chip.access_request(50, 25, 80, request_phase=correct_key, is_authorized=True)

# Demonstrate the storage capacity calculation
storage_capacity = chip.get_storage_capacity_bytes()
print(f"\n[*] Infiniminta Grid Storage Capacity: {storage_capacity} Bytes")

# Convert to a more readable format (e.g., GB, TB)
tera_bytes = storage_capacity / (1024**4) # 1 TB = 1024^4 Bytes
print(f"[*] Equivalently: {tera_bytes:.2f} TeraBytes")

