class InfinimintaDimensionalInterface:
    def __init__(self, c14_entropy_key):
        self.key = c14_entropy_key
        # The Null: A literal pit of zeros
        self.null_void = 0

    def light_to_grey(self, data_packet):
        """
        GHOSTING: Converts physical light pulses into a 'Grey' frequency ghost.
        The data is transformed into a complex interference pattern.
        """
        # Convert data to a numerical signal
        signal = np.array([ord(c) for c in data_packet])

        # Apply a Fast Fourier Transform (FFT) - This 'unfolds' the data.
        # It no longer exists in a specific location (Grey State).
        grey_ghost = np.fft.fft(signal) * self.key

        print("[L -> G] Data has been 'Ghosted'. It is now a frequency wave.")
        return grey_ghost

    def grey_to_light(self, grey_ghost):
        """
        MATERIALIZATION: Re-assembles the ghost back into physical light.
        """
        # Reverse the transform using the AI's entropy key
        reconstructed_signal = np.fft.ifft(grey_ghost / self.key)

        # Recover the OG data
        og_data = "".join([chr(int(round(np.real(x)))) for x in reconstructed_signal])
        print("[G -> L] Data Materialized. Light pulses restored to Honeycomb.")
        return og_data

    def trigger_null_snatch(self, threats):
        """
        THE VOID: Drops multiple ghosts into the Null simultaneously.
        They aren't 'deleted'—they are mathematically cancelled to zero.
        """
        num_nullified = 0
        for grey_ghost in threats:
            # Apply the Inverse Phase (Anti-Light)
            anti_wave = -1 * grey_ghost
            _ = grey_ghost + anti_wave # Total Annihilation
            num_nullified += 1

        self.null_void += num_nullified
        print(f"[NULL] {num_nullified} threats nullified. Total Null-count: {self.null_void}")
        return None # The files no longer exist in any dimension

