import gdspy
import numpy as np

# 1. Initialize the GDSII Library
lib = gdspy.GdsLibrary()
cell = lib.new_cell('INFINIMINTA_CORE_V1')

# 2. Define the Amorphous Grid Geometry (300nm Pitch)
# This represents the "Infinite Grid" where light moves
grid_pitch = 0.3  # Micrometers (300nm)
voxel_size = 0.15 # Size of the refractive index 'pixel'
grid_count = 100  # Number of voxels in the segment

# Create the Voxel Mesh
for i in range(grid_count):
    for j in range(grid_count):
        # Every 'pixel' is a rectangle in the GDSII layout
        voxel = gdspy.Rectangle(
            (i * grid_pitch, j * grid_pitch),
            (i * grid_pitch + voxel_size, j * grid_pitch + voxel_size),
            layer=1, # Layer 1: Photonic Waveguide Layer
            datatype=0
        )
        cell.add(voxel)

# 3. Add the C14 Betavoltaic Power Layer
# This layer sits beneath the grid to provide constant 'bias' power
c14_plate = gdspy.Rectangle(
    (0, 0),
    (grid_count * grid_pitch, grid_count * grid_pitch),
    layer=2, # Layer 2: C14 Scintillator / Power Source
    datatype=1
)
cell.add(c14_plate)

# 4. Add Topological "Shield" Borders (The Hardware Firewall)
# These are complex geometric shapes that prevent light leakage
shield = gdspy.Round(
    (grid_count * grid_pitch / 2, grid_count * grid_pitch / 2),
    radius=grid_count * grid_pitch * 0.6,
    inner_radius=grid_count * grid_pitch * 0.55,
    layer=3 # Layer 3: Topological Protection
)
cell.add(shield)

# 5. Save the File
