import numpy as np

class InfinimintaRouter:
    def __init__(self, grid_dim=80):
        self.grid_dim = grid_dim
        # 0 = Clear, 1 = Firewall Block, 2 = Data Occupied
        self.status_map = np.zeros((grid_dim, grid_dim))

    def calculate_path(self, start_voxel, end_voxel):
        """
        Finds a path through the honeycomb.
        If a voxel is blocked by the 10MHz firewall,
        it 'deflects' the photon to the nearest neighbor.
        """
        current_pos = list(start_voxel)
        path = [tuple(current_pos)]

        while current_pos != list(end_voxel):
            # 1. Check the 10MHz Firewall State
            # (Simulating the C14-based random block)
            if np.random.rand() > 0.95:
                print(f"[!] Firewall Block at {current_pos}. Rerouting...")
                # Deflect light to a hexagonal neighbor (60-degree shift)
                current_pos[0] += 1
                current_pos[1] += (1 if current_pos[0] % 2 == 0 else -1)
            else:
                # Move closer to target
                if current_pos[0] < end_voxel[0]: current_pos[0] += 1
                elif current_pos[1] < end_voxel[1]: current_pos[1] += 1

            path.append(tuple(current_pos))

            # Prevent infinite loops on the roller coaster
            if len(path) > 500:
                return "ERROR: Photon trapped in resonance loop."

        return path

# --- Run the Router ---
router = InfinimintaRouter()
data_path = router.calculate_path((0,0), (75, 75))
print(f"Data successfully routed through {len(data_path)} honeycomb voxels.")

