for r in range(60):
    for c in range(60):
        x, y = c * pitch * 1.5, r * pitch * np.sqrt(3)
        if c % 2 == 1: y += (pitch * np.sqrt(3)) / 2

        # Main Hexagon (outer)
        outer_points = []
        for i in range(6):
            angle = np.deg2rad(i * 60)
            px = x + hex_radius * np.cos(angle)
            py = y + hex_radius * np.sin(angle)
            outer_points.append((px, py))
        outer = gdspy.Polygon(outer_points, layer=1)

        # Inner 'Buffer Loop' - Light circles here if the router is busy
        inner_points = []
        for i in range(6):
            angle = np.deg2rad(i * 60)
            px = x + inner_buffer_radius * np.cos(angle)
            py = y + inner_buffer_radius * np.sin(angle)
            inner_points.append((px, py))
        inner = gdspy.Polygon(inner_points, layer=2)

        cell.add(outer)
        cell.add(inner)

