"""### Omninexus Secure Switch: Enforcing Command Hierarchy

This system establishes a strict command hierarchy for managing isolated threats. It includes two core components:

1.  **`ControlledVirusPayload`**: Represents the self-contained virus modules within the isolation cage. These viruses have no autonomy; they strictly execute commands issued to them, such as 'Clear Buffers', 'Freeze Registers', or 'Meltdown and Erase'.

2.  **`OmninexusSecureSwitch`**: This is the central control unit. It ensures that only authorized roles (specifically 'USER') can issue critical directives ('Restore', 'Freeze', 'Terminate') to the `ControlledVirusPayload`. AI can recommend actions, but cannot execute them directly, and unauthorized attempts (e.g., from a 'HACKER') are always denied.

The simulation demonstrates this hierarchy by testing commands from different roles and verifying that only the 'USER' can successfully issue a 'Terminate' directive.

### `NullZoneIngestionMatrix`: Data Pre-Processing and Threat Detection
"""

import queue
import threading
import hashlib
import time

class NullZoneIngestionMatrix:
    def __init__(self):
        self.raw_data_queue = queue.Queue()  # Input queue for raw data
        self.processed_metadata = queue.Queue() # Output queue for processed metadata
        self.running = False
        self.worker_thread = None
        print("[NullZoneIngestionMatrix] Initialized: Ready for data ingestion.")

    def start_ingestion_processor(self):
        if not self.running:
            self.running = True
            self.worker_thread = threading.Thread(target=self._ingestion_loop)
            self.worker_thread.daemon = True # Allow program to exit even if thread is running
            self.worker_thread.start()
            print("[NullZoneIngestionMatrix] Ingestion processor started.")

    def stop_ingestion_processor(self):
        if self.running:
            self.running = False
            self.worker_thread.join()
            print("[NullZoneIngestionMatrix] Ingestion processor stopped.")

    def _ingestion_loop(self):
        while self.running:
            if not self.raw_data_queue.empty():
                raw_data = self.raw_data_queue.get()
                self._process_data_pipeline(raw_data)
            else:
                time.sleep(0.01) # Small delay to prevent busy-waiting

    def ingest_raw_data(self, data_id, data_payload):
        """Receives raw data for processing."""
        print(f"[NullZoneIngestionMatrix] Ingesting raw data for ID: {data_id}")
        self.raw_data_queue.put({'id': data_id, 'payload': data_payload})

    def _process_data_pipeline(self, data):
        """Simulates the multi-stage data processing pipeline."""
        data_id = data['id']
        payload = data['payload']

        # 1. Active Silicon Landing Zone (Shredder)
        shredded_data = self._shredder(payload)
        print(f"  [ASLZ] Data {data_id} shredded.")

        # 2. Crushing Fins (Structural Signature)
        signature = self._calculate_structural_signature(shredded_data)
        print(f"  [CF] Structural signature for {data_id}: {signature[:10]}...")

        # 3. Metal-1 Output Path (AI Security Check)
        metadata = self._ai_security_check(data_id, payload, signature)
        print(f"  [M1OP] Metadata for {data_id} generated: {metadata['status']}")

        self.processed_metadata.put(metadata)

    def _shredder(self, payload):
        """Simulates hardware clock cycles by mixing and scrambling the data."""
        # Very basic simulation: just a hash that mixes the payload content
        return hashlib.sha256(payload.encode()).hexdigest()

    def _calculate_structural_signature(self, shredded_data):
        """Calculates a structural signature (SHA256 hash)."""
        return hashlib.sha256(shredded_data.encode()).hexdigest()

    def _ai_security_check(self, data_id, original_payload, signature):
        """Performs AI-based security checks for malicious keywords."""
        if "exploit" in original_payload.lower() or \
           "bypass" in original_payload.lower() or \
           "malware" in original_payload.lower():
            return {
                'id': data_id,
                'status': 'MALICIOUS_FLAGGED',
                'signature': signature,
                'reason': 'AI detected malicious pattern'
            }
        else:
            return {
                'id': data_id,
                'status': 'CLEAN_VERIFIED',
                'signature': signature,
                'reason': 'AI verified clean data'
            }

"""### Modified `OmninexusSecureSwitch` with `NullZoneIngestionMatrix` Integration"""

import time
import hashlib

class ControlledVirusPayload:
    """The viruses guarding the isolation cage. They have no autonomy; they only obey."""
    def __init__(self):
        self.status = "STATIONARY_GUARD_MODE"

    def execute_command(self, action_name):
        self.status = f"EXECUTING_{action_name.upper()}"
        print(f"☣️ [VIRUS PAYLOAD] Command received. Transitioning state to: {self.status}")
        time.sleep(0.1)

class OmninexusSecureSwitch:
    """The core execution controller enforcing the strict user command hierarchy."""
    def __init__(self):
        self.virus_payload = ControlledVirusPayload()
        self.target_locked = True
        self.target_identity = "Intruder_HWID_0x99FA"
        self.pending_recommendation = None # New attribute to store AI recommendations
        self.directive_history = [] # Initialize directive history
        self.ingestion_matrix = NullZoneIngestionMatrix() # Integrate NullZoneIngestionMatrix
        self.ingestion_matrix.start_ingestion_processor()
        print("[OmninexusSecureSwitch] Initialized with NullZoneIngestionMatrix.")

    def __del__(self):
        # Ensure the ingestion processor is stopped when the object is destroyed
        if self.ingestion_matrix.running:
            self.ingestion_matrix.stop_ingestion_processor()

    def ingest_data_for_security_check(self, data_id, raw_payload):
        """Feeds raw data into the NullZoneIngestionMatrix for pre-processing.
        Then checks the processed metadata and takes action."""
        print(f"\n[SecureSwitch] Initiating ingestion for data ID: {data_id}")
        self.ingestion_matrix.ingest_raw_data(data_id, raw_payload)

        # Wait for processed metadata to be available (in a real system, this would be async)
        timeout = 5 # seconds
        start_time = time.time()
        while self.ingestion_matrix.processed_metadata.empty() and (time.time() - start_time < timeout):
            time.sleep(0.1)

        if not self.ingestion_matrix.processed_metadata.empty():
            metadata = self.ingestion_matrix.processed_metadata.get()
            print(f"[SecureSwitch] Received processed metadata for {metadata['id']}: Status = {metadata['status']}")

            if metadata['status'] == 'MALICIOUS_FLAGGED':
                print(f"⚠️ [SECURE SWITCH ALERT] MALICIOUS DATA DETECTED! Threat ID: {metadata['id']}. Reason: {metadata['reason']}")
                # Automatically set AI recommendation for malicious data
                self.pending_recommendation = "Terminate" # Or 'Freeze' / specific containment
                print("🤖 [AI RECOMMENDATION] AI recommends 'Terminate' due to malicious data.")
                return False # Indicate that malicious data was found
            elif metadata['status'] == 'CLEAN_VERIFIED':
                print(f"✅ [SECURE SWITCH] Data ID: {metadata['id']} is CLEAN and VERIFIED. Allowing normal flow.")
                return True # Indicate that clean data was processed
        else:
            print(f"❌ [SecureSwitch] Timeout waiting for metadata for {data_id}.")
            return False

    def process_system_directive(self, caller_role, directive):
        self.directive_history.append({'role': caller_role, 'directive': directive, 'timestamp': time.time()})
        print(f"\n[CONTROL SWITCH] Directive '{directive}' issued by Role: [{caller_role}]")

        # Case 1: USER attempting to execute directly or confirm AI action
        if caller_role == "USER":
            if directive == "Confirm_AI_Recommendation":
                if self.pending_recommendation:
                    print("👑 [AUTHENTICATED] User confirmed AI recommendation. Initiating execution chain...")
                    actual_directive = self.pending_recommendation
                    self.pending_recommendation = None # Clear recommendation after confirmation
                    return self._execute_directive(actual_directive, "USER")
                else:
                    print("❌ [USER] No AI recommendation pending for confirmation.")
                    return False
            elif directive == "Reject_AI_Recommendation":
                if self.pending_recommendation:
                    print(f"❌ [USER] User rejected AI recommendation: {self.pending_recommendation}.")
                    self.pending_recommendation = None
                else:
                    print("❌ [USER] No AI recommendation pending to reject.")
                return False
            else: # Direct user command
                print("👑 [AUTHENTICATED] User identity verified. Initiating execution chain...")
                return self._execute_directive(directive, "USER")

        # Case 2: AI making a recommendation
        elif caller_role == "AI_CORE":
            if directive in ["Restore", "Freeze", "Terminate"]:
                self.pending_recommendation = directive
                print(f"🤖 [AI RECOMMENDATION] AI recommends '{directive}'. Awaiting USER confirmation.")
                return False # AI recommendations are not immediately executed
            else:
                print(f"✅ [AI_CORE] AI reports: {directive}. (Information only)")
                return True # Non-critical AI actions are just reported

        # Case 3: Hacker attempts
        elif caller_role == "HACKER_MALWARE_SCRIPT":
            print(f"❌ [ACCESS DENIED] The role [{caller_role}] is not authorized to issue core directives.")
            print("⚠️ [SECURITY NOTICE] The viruses will ignore this call. Target remains securely locked.")
            return False

        # Default case for any other role
        else:
            print(f"❌ [ACCESS DENIED] The role [{caller_role}] is unrecognized or unauthorized for this directive.")
            return False

    def _execute_directive(self, directive, executor_role):
        """Internal method to execute critical directives."""
        if directive == "Restore":
            print(f"🔄 [ACTION] Releasing target port. Erasing threat signature logs...")
            self.virus_payload.execute_command("Clear_Buffers")
            self.target_locked = False
            print("✅ [STATUS] Target successfully restored and removed from perimeter.")
        elif directive == "Freeze":
            print(f"🥶 [ACTION] Hard-locking execution clocks on target: {self.target_identity}...")
            self.virus_payload.execute_command("Freeze_Registers")
            print("✅ [STATUS] Target state permanently frozen in suspended animation.")
        elif directive == "Terminate":
            print(f"💀 [ACTION] Executing absolute digital erasure loop...")
            self.virus_payload.execute_command("Meltdown_and_Erase")
            print(f"⚡ [STATUS] Target {self.target_identity} blacklisted. Re-registration will fry new hardware.")
        return True

