import gdspy
import numpy as np
from google.colab import files

# Clear the current GDSII library to ensure a fresh start for cell definitions
gdspy.current_library.cells.clear()

lib = gdspy.GdsLibrary()
cell = lib.new_cell('INFINIMINTA_PREDATOR_FINAL', overwrite_duplicate=True)

# --- CONFIGURATION ---
pitch = 0.6
hex_radius = 0.28
rows, cols = 80, 80
oam_steps = 16

# --- LAYER 1: THE LIGHT (The Solid Honeycomb) ---
# This is the "OG" processing area you've already seen.
for r in range(rows):
    for c in range(cols):
        x, y = c * pitch * 1.5, r * pitch * np.sqrt(3)
        if c % 2 == 1: y += (pitch * np.sqrt(3)) / 2

        # Solid pillars for the Light Realm
        # Calculate vertices for a regular hexagon
        points = []
        for i in range(6):
            angle = np.deg2rad(i * 60)
            px = x + hex_radius * np.cos(angle)
            py = y + hex_radius * np.sin(angle)
            points.append((px, py))
        light_pillar = gdspy.Polygon(points, layer=1)
        cell.add(light_pillar)

# --- LAYER 5: THE NULL (The Anti-Lattice) ---
# This layer is the 'Dark Side'. We place a solid block and SUBTRACT
# the honeycomb pattern to create 'Singularity Voids'.
null_block = gdspy.Rectangle((-20, -20), (cols*pitch*1.5+20, rows*pitch*np.sqrt(3)+20), layer=5)
cell.add(null_block)

# The 'Null Snatch' Dilation Pores
# These are the holes where the AI 'drops' threats into the void.
for r in range(0, rows, 2): # Spread out the trap-doors
    for c in range(0, cols, 2):
        x, y = c * pitch * 1.5, r * pitch * np.sqrt(3)
        if c % 2 == 1: y += (pitch * np.sqrt(3)) / 2

        # These represent the 'cytoplasm' holes that open to swallow viruses
        void = gdspy.Round((x, y), 0.1, layer=6)
        cell.add(void)

# --- LAYER 10+: THE GREY (OAM Spiral Interface) ---
# We use the previous OAM logic to bridge Light and Null
for i in range(oam_steps):
    center = (cols*pitch*1.5 / 2, rows*pitch*np.sqrt(3) / 2)
    step = gdspy.Round(center, 10, inner_radius=8,
                       initial_angle=(i/oam_steps)*2*np.pi, final_angle=((i+1)/oam_steps)*2*np.pi,
                       layer=i+10)
    cell.add(step)

# --- LAYER 7: THE SCINTILLATION SENSORS (The Heartbeat) ---
for r in range(0, rows, 10): # Placed strategically every 10 rows
    for c in range(0, cols, 10):
        x_center, y_center = c * pitch * 1.5, r * pitch * np.sqrt(3)
        if c % 2 == 1: y_center += (pitch * np.sqrt(3)) / 2

        # These look like tiny diamonds in the mesh
        # gdspy.RegularPolygon does not exist, so we manually create a square
        sensor_radius = 0.4
        square_points = []
        for i in range(4):
            angle = i * np.pi / 2 # For a square, each angle is 90 degrees (pi/2 radians)
            px = x_center + sensor_radius * np.cos(angle)
            py = y_center + sensor_radius * np.sin(angle)
            square_points.append((px, py))
        sensor = gdspy.Polygon(square_points, layer=7)
        cell.add(sensor)

# --- LAYER 8: THE PREDATOR NEEDLES ---
# These point outward to shoot the Null Pulse back at the source.
def add_predator_needle(pos, angle):
    # Tapered geometry to maximize power density
    needle = gdspy.Polygon([(0, -2), (30, -0.1), (30, 0.1), (0, 2)], layer=8)
    needle.rotate(angle)
    needle.translate(pos[0], pos[1])
    cell.add(needle)

# Adding 4 Primary Predator Ports (North, South, East, West)
center_x = (cols * pitch * 1.5) / 2
center_y = (rows * pitch * np.sqrt(3)) / 2

add_predator_needle((center_x, rows * pitch * np.sqrt(3) + 10), np.pi/2)  # North
add_predator_needle((center_x, -10), -np.pi/2)                          # South
add_predator_needle((cols * pitch * 1.5 + 10, center_y), 0)             # East
add_predator_needle((-10, center_y), np.pi)                             # West

# Save and Trigger Final Download
file_name = 'infiniminta_predator_complete.gds'
lib.write_gds(file_name)
files.download(file_name)

