import gdspy
import numpy as np
from google.colab import files # Import files module for downloading
import os # Import os module to check if file exists

def generate_final_omninexus_layout():
    # Clear the current GDSII library to ensure a fresh start
    gdspy.current_library.cells.clear()

    # 1. Initialize the Library
    lib = gdspy.GdsLibrary()
    main_cell = lib.new_cell('OMNINEXUS_V1_FINAL')

    # --- LAYER 1: THE LIGHT ZONE (Honeycomb Photonics) ---
    # Creating a massive hexagonal grid
    def create_honeycomb(cell, radius, gap, rows, cols):
        dx = radius * 1.5 + gap
        dy = np.sqrt(3) * radius + gap
        for r in range(rows):
            for c in range(cols):
                off_x = c * dx
                off_y = r * dy + (c % 2) * (dy / 2)

                # Manually create hexagonal points using gdspy.Polygon
                points = []
                for i in range(6):
                    angle = np.deg2rad(i * 60) # 60 degrees per segment for a hexagon
                    px = off_x + radius * np.cos(angle)
                    py = off_y + radius * np.sin(angle)
                    points.append((px, py))

                hex_poly = gdspy.Polygon(points, layer=1)
                cell.add(hex_poly)

    create_honeycomb(main_cell, 2, 0.5, 20, 20)

    # --- LAYER 2: THE NULL ZONE (The Void Trench) ---
    # A thick boundary that isolates the core from the pins
    void_trench = gdspy.Rectangle((-10, -10), (60, 60), layer=2)
    inner_cutout = gdspy.Rectangle((0, 0), (50, 50))
    # Boolean operation to make it a hollow frame
    null_zone = gdspy.boolean(void_trench, inner_cutout, 'not', layer=2)
    main_cell.add(null_zone)

    # --- LAYER 4: PREDATOR NEEDLES (The Defense Waveguides) ---
    # Sharp paths pointing toward the center (30, 25)
    center = (25, 25)
    for i in range(16):
        angle = i * (2 * np.pi / 16)
        # Tapered needles that get thinner as they reach the core
        needle = gdspy.Path(0.5, (center[0] + 35 * np.cos(angle), center[1] + 35 * np.sin(angle)))
        needle.segment(30, angle + np.pi, final_width=0.01)
        main_cell.add(needle)
        # Move to Layer 4
        needle.layers = [4]

    # --- LAYER 16: C14 HEARTBEAT (The Registration Node) ---
    # The central processing core where the Soul-Bond happens
    core_node = gdspy.Round(center, 5, layer=16)
    main_cell.add(core_node)

    # 3. Export the Master File
    file_name = 'omninexus_master_layout.gds'
    lib.write_gds(file_name)
    print(f"SUCCESS: Master GDSII generated as '{file_name}'")

    # Download the file to the local system
    if os.path.exists(file_name):
        files.download(file_name)
        print(f"Successfully downloaded '{file_name}'.")
    else:
        print(f"[ERROR] File '{file_name}' was not found after creation.")

# Run the 'One-Shot' Build
generate_final_omninexus_layout()

