import numpy as np
import matplotlib.pyplot as plt
from matplotlib.animation import FuncAnimation
from google.colab import files

def render_assembly_mp4():
    fig = plt.figure(figsize=(10, 10), facecolor='black')
    ax = fig.add_subplot(111, projection='3d')
    ax.set_facecolor('black')

    # Grid Data for the Layers
    n_hex = 30
    hx = np.random.uniform(-10, 10, n_hex)
    hy = np.random.uniform(-10, 10, n_hex)

    ax.set_xlim(-15, 15)
    ax.set_ylim(-15, 15)
    ax.set_zlim(0, 20)
    ax.axis('off')

    def update(frame):
        ax.clear()
        ax.set_facecolor('black')
        ax.axis('off')

        # Calculate vertical "Drop" for each layer
        # They start high and stack down to Z=0
        p = min(1, frame / 100)

        # LAYER 1: LIGHT ZONE (Bottom)
        z1 = max(0, 15 * (1 - p))
        ax.scatter(hx, hy, z1, s=100, marker='h', color='#8A2BE2', edgecolors='white', alpha=0.6, label="Light Zone")

        # LAYER 2: NULL ZONE (Middle)
        if frame > 20:
            p2 = min(1, (frame - 20) / 80)
            z2 = max(5, 20 * (1 - p2))
            # Drawing a frame for the Null Zone
            tx = np.array([-12, 12, 12, -12, -12])
            ty = np.array([-12, -12, 12, 12, -12])
            ax.plot(tx, ty, z2, color='red', lw=3, label="Null Zone Barrier")

        # LAYER 4: PREDATOR NEEDLES (Top)
        if frame > 40:
            p3 = min(1, (frame - 40) / 60)
            z3 = max(10, 25 * (1 - p3))
            for i in range(8):
                angle = i * np.pi/4
                ax.plot([0, 10*np.cos(angle)], [0, 10*np.sin(angle)], [z3, z3], color='white', lw=2)

        # Rotating the camera for that cinematic 'Pro' look
        ax.view_init(elev=20, azim=frame)
        return []

    ani = FuncAnimation(fig, update, frames=150, interval=40)
    output_file = "omninexus_final_assembly.mp4"
    ani.save(output_file, writer='ffmpeg', fps=30)
    plt.close()

    files.download(output_file)
    print("Assembly Rendered. Your GDSII is now a 3D Entity.")

render_assembly_mp4()

