import numpy as np
from scipy.io.wavfile import write as write_wav

# Audio configuration for a panic sound effect
samplerate = 44100  # samples per second
duration = 2.0      # seconds
frequency = 440     # Hz (A4 note)
fade_duration = 0.1 # seconds for fade in/out

# Generate time vector
t_audio = np.linspace(0., duration, int(samplerate * duration), endpoint=False)

# Generate a sine wave (beep)
amplitude = 0.5
data = amplitude * np.sin(2 * np.pi * frequency * t_audio)

# Apply fade in/out to avoid clicks
fade_in_len = int(fade_duration * samplerate)
fade_out_len = int(fade_duration * samplerate)

fade_in = np.linspace(0., 1., fade_in_len)
fade_out = np.linspace(1., 0., fade_out_len)

data[:fade_in_len] *= fade_in
data[-fade_out_len:] *= fade_out

# Ensure data is in a format suitable for WAV (e.g., int16)
data_int16 = (data * 32767).astype(np.int16)

audio_filename = "panic_sound.wav"
write_wav(audio_filename, samplerate, data_int16)
print(f"Generated audio file: {audio_filename}")

import numpy as np
from scipy.io.wavfile import write as write_wav

# Audio configuration for a 'pounding' sound effect
samplerate = 44100  # samples per second
duration = 2.0      # seconds
frequency_start = 80 # Hz (low rumble)
frequency_end = 20   # Hz (deep thud)

# Generate time vector
t_pounding = np.linspace(0., duration, int(samplerate * duration), endpoint=False)

# Generate a decaying sine wave for a 'thud' sound
amplitude_pounding = 0.8 * np.exp(-3 * t_pounding)

# Frequency sweep downwards for a 'heavy' feel
pounding_data = amplitude_pounding * np.sin(2 * np.pi * (frequency_start + (frequency_end - frequency_start) * (t_pounding / duration)) * t_pounding)

# Ensure data is in a format suitable for WAV (e.g., int16)
pounding_data_int16 = (pounding_data * 32767).astype(np.int16)

pounding_audio_filename = "pounding_sound.wav"
write_wav(pounding_audio_filename, samplerate, pounding_data_int16)
print(f"Generated audio file: {pounding_audio_filename}")

