import numpy as np
import matplotlib.pyplot as plt
from matplotlib.animation import FuncAnimation
from google.colab import files
import os # Import os for file path manipulation

def render_panic_pulse_mp4():
    fig, ax = plt.subplots(figsize=(10, 6), facecolor='black')
    ax.set_facecolor('black')

    # 1. The Pulse Line (Heart Rate)
    # 2. The Data Stream (The Lore)
    t = np.linspace(0, 10, 300)

    # High Stress Pulse (The Trigger)
    pulse = np.sin(2 * np.pi * 2 * t) + np.random.normal(0, 0.1, 300)

    line_pulse, = ax.plot([], [], color='red', lw=2, label="Biometric Stress (HRV)")
    line_decoy, = ax.plot([], [], color='cyan', lw=1, alpha=0.5, label="Decoy Data Stream")
    line_real, = ax.plot([], [], color='lime', lw=3, label="Real Grey Zone (ENCRYPTED)")

    ax.set_xlim(0, 10)
    ax.set_ylim(-3, 3)
    ax.axis('off')
    ax.legend(loc='upper right', facecolor='black', edgecolor='white', labelcolor='white')

    def animate(i):
        # Update Pulse
        line_pulse.set_data(t[:i], pulse[:i])

        # When stress hits a certain point, the 'Real' line disappears
        # and the 'Decoy' line takes over.
        if i > 150:
            # Panic Detected! Real line goes flat/invisible
            line_real.set_data(t[:150], np.zeros(150))
            line_decoy.set_data(t[:i], np.sin(5 * t[:i]) * 0.5)
            ax.set_title("!!! PANIC DETECTED: DEPLOYING DECOY VAULT !!!", color='red', fontsize=15)
        else:
            line_real.set_data(t[:i], np.sin(5 * t[:i]))
            ax.set_title("OMNINEXUS: AUTHENTICATING...", color='cyan', fontsize=12)

        return line_pulse, line_decoy, line_real

    ani = FuncAnimation(fig, animate, frames=300, interval=30, blit=True)

    video_output_file = "omninexus_panic_protocol_video.mp4"
    final_output_file = "omninexus_panic_protocol_with_sound.mp4"
    audio_file = "panic_sound.wav"

    # Save video without audio first
    ani.save(video_output_file, writer='ffmpeg', fps=30, extra_args=['-vcodec', 'libx264', '-pix_fmt', 'yuv420p'])
    plt.close()
    print(f"Video rendered: {video_output_file}")

    # Check if audio file exists and merge
    if os.path.exists(audio_file):
        print(f"Merging video with audio from {audio_file}...")
        # Use ffmpeg command to merge video and audio
        # -y overwrites output file without asking
        # -i for input video, -i for input audio
        # -c:v copy copies video stream as is
        # -c:a aac encodes audio to aac, -b:a 192k sets audio bitrate
        # -map 0:v:0 maps video stream from first input (video)
        # -map 1:a:0 maps audio stream from second input (audio)
        ffmpeg_command = f"ffmpeg -y -i {video_output_file} -i {audio_file} -c:v copy -c:a aac -b:a 192k -map 0:v:0 -map 1:a:0 {final_output_file}"
        os.system(ffmpeg_command)

        if os.path.exists(final_output_file):
            files.download(final_output_file)
            print(f"Panic Protocol MP4 with sound rendered: {final_output_file}")
        else:
            print(f"[ERROR] Failed to create {final_output_file}. Only video available.")
            files.download(video_output_file)
            print(f"Downloading video only: {video_output_file}")
    else:
        print(f"[WARNING] Audio file {audio_file} not found. Downloading video only.")
        files.download(video_output_file)
        print(f"Panic Protocol MP4 rendered (no sound): {video_output_file}")

render_panic_pulse_mp4()

