def render_infinity_pounding_mp4_with_sound():
    # Setup the Canvas
    fig, ax = plt.subplots(figsize=(8, 8), facecolor='black')
    ax.set_facecolor('black')

    # 1. THE PARTICLES (Data Points)
    n_particles = 200
    # Random positions in a shell
    theta = np.random.uniform(0, 2*np.pi, n_particles)
    r = np.random.uniform(10, 15, n_particles)
    x = r * np.cos(theta)
    y = r * np.sin(theta)

    # Colors for the 3 Zones
    # Grey = Storage, Cyan = Light, Violet = Null
    colors = np.random.choice(['#808080', '#00FFFF', '#8A2BE2'], n_particles)

    scat = ax.scatter(x, y, s=30, c=colors, edgecolors='white', linewidth=0.2)

    # The Core (The Singularity)
    core = ax.scatter([0], [0], s=100, color='white', marker='o', alpha=1)

    ax.set_xlim(-16, 16)
    ax.set_ylim(-16, 16)
    ax.axis('off')

    def update(frame):
        # The 'Pounding' Effect: Gravity increases exponentially
        # The data is being crushed into the center
        p = (frame % 50) / 50 # Loops every 50 frames

        # Power function creates the 'Pounding' snap effect
        strength = p**3

        new_x = x * (1 - strength)
        new_y = y * (1 - strength)

        # The core glows brighter as data hits it
        core_size = 100 + (strength * 2000)
        core.set_sizes([core_size])

        scat.set_offsets(np.c_[new_x, new_y])

        # AI Control logic: As they get closer, they all turn White (Pure Info)
        if p > 0.8:
            scat.set_facecolor('white')
        else:
            scat.set_facecolor(colors)

        return scat, core

    # 150 frames for 3 massive 'pounding' cycles
    ani = FuncAnimation(fig, update, frames=150, interval=30, blit=True)

    video_output_file = "omninexus_infinite_processing_video.mp4"
    final_output_file = "omninexus_infinite_processing_with_sound.mp4"
    audio_file = "pounding_sound.wav"

    # Save video without audio first
    ani.save(video_output_file, writer='ffmpeg', fps=30, dpi=100,
             extra_args=['-vcodec', 'libx264', '-pix_fmt', 'yuv420p'])
    plt.close()
    print(f"Video rendered: {video_output_file}")

    # Check if audio file exists and merge
    if os.path.exists(audio_file):
        print(f"Merging video with audio from {audio_file}...")
        ffmpeg_command = f"ffmpeg -y -i {video_output_file} -i {audio_file} -c:v copy -c:a aac -b:a 192k -map 0:v:0 -map 1:a:0 {final_output_file}"
        os.system(ffmpeg_command)

        if os.path.exists(final_output_file):
            files.download(final_output_file)
            print(f"Infinity Pounding MP4 with sound rendered: {final_output_file}")
        else:
            print(f"[ERROR] Failed to create {final_output_file}. Only video available.")
            files.download(video_output_file)
            print(f"Downloading video only: {video_output_file}")
    else:
        print(f"[WARNING] Audio file {audio_file} not found. Downloading video only.")
        files.download(video_output_file)
        print(f"Infinity Pounding MP4 rendered (no sound): {video_output_file}")

render_infinity_pounding_mp4_with_sound()

import gdspy
import matplotlib.pyplot as plt
from mpl_toolkits.mplot3d import Axes3D
from mpl_toolkits.mplot3d.art3d import Poly3DCollection # Import Poly3DCollection
import numpy as np

# Load the GDSII library
lib = gdspy.GdsLibrary(infile='infiniminta_omninexus_total.gds')
cell_name = 'INFINIMINTA_OMNINEXUS_TOTAL'
cell = lib.cells[cell_name]

fig = plt.figure(figsize=(10, 8))
ax = fig.add_subplot(111, projection='3d')

layer_colors = {
    1: 'skyblue',  # Light Zone
    2: 'lightgray',  # Grey Zone
    5: 'darkgrey', # Null Zone
    7: 'gold',     # C14 Sensors
    8: 'red'       # Predator Ports
}

layer_z_offset = {
    1: 0,      # Base layer
    2: 0.5,    # Slightly above Light
    5: -0.5,   # Below Light
    7: 1,      # Above all
    8: 0.75    # Above Light, for visibility
}

all_x = []
all_y = []
all_z = []

# Check if any polygons exist in the cell
if not cell.polygons:
    print(f"[WARNING] Cell '{cell_name}' contains no polygons to plot.")
else:
    print(f"[*] Found {len(cell.polygons)} polygon sets in cell '{cell_name}'.")

# Iterate through all polygons in the cell
for polygon_set in cell.polygons:
    layer = polygon_set.layers[0] # Assuming one layer per polygon set
    color = layer_colors.get(layer, 'green') # Default to green for other layers
    z_offset = layer_z_offset.get(layer, 0)

    for points in polygon_set.polygons:
        # Prepare vertices for Poly3DCollection
        verts = [[(p[0], p[1], z_offset) for p in points]]

        # Create and add Poly3DCollection for filled polygons
        poly3d = Poly3DCollection(verts, facecolors=color, linewidths=0.5, edgecolors='k', alpha=0.3)
        ax.add_collection3d(poly3d)

        # Also draw edges for clarity using ax.plot
        x = [p[0] for p in points]
        y = [p[1] for p in points]
        z = [z_offset] * len(points)

        # Add the first point again to close the polygon in 3D plot
        x.append(x[0])
        y.append(y[0])
        z.append(z[0])
        ax.plot(x, y, z, color=color, alpha=0.8)

        all_x.extend(x)
        all_y.extend(y)
        all_z.extend(z)

ax.set_xlabel('X Dimension (um)')
ax.set_ylabel('Y Dimension (um)')
ax.set_zlabel('Layer Z-Offset (um)')
ax.set_title(f'3D Visualization of {cell_name} GDSII Layout')

# Calculate dynamic limits based on all plotted points
if all_x and all_y and all_z:
    min_x, max_x = min(all_x), max(all_x)
    min_y, max_y = min(all_y), max(all_y)
    min_z, max_z = min(all_z), max(all_z)

    # Use cell.get_bounding_box() for the overall cell dimensions
    bbox = cell.get_bounding_box() # Corrected: Call get_bounding_box on the cell object
    if bbox is not None:
        min_x = min(min_x, bbox[0][0])
        max_x = max(max_x, bbox[1][0])
        min_y = min(min_y, bbox[0][1])
        max_y = max(max_y, bbox[1][1])

    range_x = max_x - min_x
    range_y = max_y - min_y
    range_z = max_z - min_z

    # Determine the maximum range across all dimensions to set equal aspect ratio
    max_range = max(range_x, range_y, range_z)

    mid_x = (min_x + max_x) / 2
    mid_y = (min_y + max_y) / 2
    mid_z = (min_z + max_z) / 2

    # Set limits to make the plot appear cubic
    ax.set_xlim(mid_x - max_range / 2, mid_x + max_range / 2)
    ax.set_ylim(mid_y - max_range / 2, mid_y + max_range / 2)
    ax.set_zlim(mid_z - max_range / 2, mid_z + max_range / 2)
else:
    print("[WARNING] No polygon data found to set plot limits or plot was empty.")

plt.show()

