"""### Light-Speed Data Propagation and Switching

This simulation demonstrates the Omninexus system's ability to process and switch data at near light-speed across its various zones. It showcases:

1.  **Instantaneous Data Generation**: Data is 'materialized' in the Light Zone.
2.  **Rapid Switching/Routing**: The system quickly identifies data as 'clean' or 'malicious'.
3.  **Zero-Latency Propagation**: Clean data is 'ghosted' to the Grey Zone for storage and then instantly 'materialized' back to the Light Zone. Malicious data is immediately 'nullified'.

This highlights the theoretical processing speedup achieved by the photonic architecture, where operations occur almost instantaneously.
"""

import numpy as np
import time

class OmninexusLightSpeedPropagator:
    def __init__(self):
        self.light_zone_buffer = []  # Active data processing
        self.grey_zone_vault = []    # Ghosted data storage
        self.null_zone_count = 0     # Threat eradication counter
        print("[OmninexusLightSpeedPropagator] Initialized: Ready for light-speed operations.")

    def generate_data(self, data_id, is_malicious=False):
        """Simulates instantaneous data generation in the Light Zone."""
        data_packet = {'id': data_id, 'payload': f'Data from {data_id}', 'malicious': is_malicious}
        self.light_zone_buffer.append(data_packet)
        print(f"[Light Zone] Data '{data_id}' materialized. Malicious: {is_malicious}")
        return data_packet

    def propagate_and_switch(self, data_packet):
        """Simulates near-instantaneous decision and propagation."""
        start_time = time.perf_counter_ns() # High-resolution timer

        if data_packet['malicious']:
            print(f"  [Null Zone] Malicious data '{data_packet['id']}' detected! Initiating Null Snatch...")
            self.null_zone_count += 1
            # Simulate immediate deletion/disintegration
            self.light_zone_buffer.remove(data_packet)
            status = "NULLIFIED"
        else:
            print(f"  [Grey Zone] Clean data '{data_packet['id']}' confirmed. Ghosting to storage...")
            self.grey_zone_vault.append(data_packet)
            # Simulate retrieving it immediately after ghosting for processing/use
            self.light_zone_buffer.remove(data_packet)
            self.light_zone_buffer.append(data_packet) # Materialized back for active use
            status = "PROPAGATED_AND_MATERIALIZED"

        end_time = time.perf_counter_ns()
        propagation_time_ns = end_time - start_time
        print(f"  [Processing] Propagation and Switching for '{data_packet['id']}' took: {propagation_time_ns} nanoseconds. Status: {status}")
        return status, propagation_time_ns

    def run_simulation(self, num_clean, num_malicious):
        """Runs a full simulation of data generation, propagation, and switching."""
        total_propagation_time_ns = 0

        print("\n--- Running Light-Speed Propagation Simulation ---")

        for i in range(num_clean):
            clean_data = self.generate_data(f"CleanData_{i+1}", is_malicious=False)
            _, time_taken = self.propagate_and_switch(clean_data)
            total_propagation_time_ns += time_taken

        for i in range(num_malicious):
            malicious_data = self.generate_data(f"MaliciousData_{i+1}", is_malicious=True)
            _, time_taken = self.propagate_and_switch(malicious_data)
            total_propagation_time_ns += time_taken

        print("\n--- Simulation Results ---")
        print(f"Total Clean Data in Grey Zone Vault: {len(self.grey_zone_vault)}")
        print(f"Total Threats Nullified: {self.null_zone_count}")
        print(f"Total Simulated Processing Time for {num_clean + num_malicious} packets: {total_propagation_time_ns} nanoseconds")
        print("Theoretical Speedup: Operations occur at near-zero latency, simulating light-speed processing across architectural layers.")


# --- DEMONSTRATION ---
propagator = OmninexusLightSpeedPropagator()
propagator.run_simulation(num_clean=5, num_malicious=2)

