import numpy as np
import matplotlib.pyplot as plt
from matplotlib.animation import FuncAnimation
from google.colab import files

def render_oblivion_sequence():
    fig, ax = plt.subplots(figsize=(10, 6), facecolor='black')
    ax.set_facecolor('black')

    # Hacker (The Red Dot)
    dot, = ax.plot([0], [5], 'ro', markersize=10, label="Hacker Connection")

    # The Pseudo-Dimension (Fractal Grid)
    grid_x, grid_y = np.meshgrid(np.linspace(-10, 10, 20), np.linspace(-10, 10, 20))
    grid = ax.scatter(grid_x, grid_y, s=10, color='lime', alpha=0.3)

    ax.set_xlim(-12, 12)
    ax.set_ylim(-12, 12)
    ax.axis('off')

    def update(frame):
        # Phase 1: Entry (0-30)
        if frame < 30:
            dot.set_data([0], [5 - (frame/10)])
            ax.set_title("PSEUDO-DIMENSION ENTERED", color='lime')

        # Phase 2: The "Soup-Logic" Trigger (30-60)
        elif frame < 60:
            # Grid starts glitching out
            new_offsets = np.c_[grid_x.flatten() + np.random.normal(0, 0.5),
                               grid_y.flatten() + np.random.normal(0, 0.5)]
            grid.set_offsets(new_offsets)
            grid.set_color('red')
            ax.set_title("!!! VIRUS REPLICA ACTIVATED: SOUP-LOGIC.EXE !!!", color='red')

        # Phase 3: Total Erasure (60-120)
        else:
            # Everything collapses and turns to 'Static'
            static = np.random.uniform(-12, 12, (400, 2))
            grid.set_offsets(static)
            grid.set_alpha(max(0, 1 - (frame-60)/60))
            dot.set_alpha(0)
            ax.set_title("IDENTITY ERASED. HARDWARE MELTED.", color='white')

        return grid, dot

    ani = FuncAnimation(fig, update, frames=120, interval=40)
    output_file = "omninexus_oblivion_trap.mp4"
    ani.save(output_file, writer='ffmpeg', fps=30)
    plt.close()

    files.download(output_file)
    print("Oblivion Sequence Rendered. The hacker is dead.")

render_oblivion_sequence()

