import json

def user_authority_panel(hacker_id_vault):
    print("--- OMNINEXUS AUTHORITY COMMAND ---")
    print(f"TARGET IDENTIFIED: {hacker_id_vault['name']}")
    print(f"STATUS: {hacker_id_vault['status']} - All Assets Locked")

    choice = input("\nSelect Action: [1] Terminate | [2] Keep Frozen | [3] Restore: ")

    system_response = "INVALID_CHOICE"

    if choice == "1":
        print("!!! WARNING: TERMINATION IS PERMANENT !!!")
        confirm = input("Confirm Identity Deletion? (Y/N): ")
        if confirm.lower() == 'y':
            system_response = "SIGNAL_SENT: HARDWARE_MELT_ON_REGISTRATION"
            hacker_id_vault['status'] = "TERMINATED"
    elif choice == "2":
        system_response = "STASIS_MAINTAINED: NO_ACCESS_ALLOWED"
        hacker_id_vault['status'] = "FROZEN"
    elif choice == "3":
        system_response = "RESTORE_SENT: IDENTITY_CLEANSED"
        hacker_id_vault['status'] = "RESTORED"

    # Save the updated hacker status to a JSON file
    if system_response != "INVALID_CHOICE":
        output_filename = f"{hacker_id_vault['name']}_status.json"
        try:
            with open(output_filename, 'w') as f:
                json.dump(hacker_id_vault, f, indent=4)
            print(f"[SUCCESS] Hacker status saved to {output_filename}")
        except Exception as e:
            print(f"[ERROR] Failed to save hacker status: {e}")

    return system_response

