import numpy as np
import matplotlib.pyplot as plt
from matplotlib.animation import FuncAnimation
from google.colab import files

def render_shredder_bridge_mp4():
    fig, ax = plt.subplots(figsize=(10, 6), facecolor='black')
    ax.set_facecolor('black')

    # 1. Light Zone Data
    light_data = ax.text(-8, 0, "1010110", color='cyan', fontsize=20, ha='center', fontweight='bold')

    # 2. The Bridge (Middle)
    bridge_line = ax.axvline(0, color='white', linestyle='--', alpha=0.5)
    ax.text(0, 8, "THE BRIDGE", color='white', ha='center')

    # 3. Grey Zone Data (Starts Empty)
    grey_data = ax.text(8, 0, "", color='magenta', fontsize=20, ha='center')

    ax.set_xlim(-12, 12)
    ax.set_ylim(-10, 10)
    ax.axis('off')

    def update(frame):
        # Data moving across the bridge
        x_pos = -8 + (frame/4)

        if x_pos < 0:
            light_data.set_position((x_pos, 0))
            light_data.set_text("1010110")
            light_data.set_color('cyan')
        else:
            # The Moment of Conversion
            light_data.set_position((x_pos, 0))
            # Changed characters to avoid Matplotlib math text parsing issues
            shuffled = "".join(np.random.choice(list("!@#*()_+-=<>?[]{}\\|;:,./"), 7))
            light_data.set_text(shuffled)
            light_data.set_color('magenta')
            ax.set_title("BRIDGE CONVERSION: LIGHT -> GIBBERISH", color='white')

    ani = FuncAnimation(fig, update, frames=80, interval=50)
    output_file = "omninexus_shredder_bridge.mp4"
    ani.save(output_file, writer='ffmpeg', fps=30)
    plt.close()

    files.download(output_file)
    print("Bridge Conversion Rendered. Data is now safely unreadable.")

render_shredder_bridge_mp4()

