import tidy3d as td

# Define the silicon material
silicon_material = td.Medium(name='silicon', permittivity=12.0)

# Create a physical 3D structure representing an intersection path in your grid
# Tidy3D measures strictly in micrometers (microns)
physical_grid_wire = td.Structure(
    geometry=td.Box(
        center=(0, 0, 0),       # Positioned exactly at the center of our simulation universe
        size=(10, 0.4, 0.22)    # 10 microns long, 400nm wide, 220nm thick (standard chip size)
    ),
    medium=silicon_material
)

print("Physical grid wire structure created:")
print(physical_grid_wire)

# 1. Define the boundaries of the test arena (12µm x 12µm x 4µm space)
domain_size = (12, 12, 4)

# 2. Place a pulse source to simulate a real data packet entering the grid
wave_source = td.PointDipole(
    center=(-4.5, 0, 0), # Placed at the left entrance of the physical wire
    source_time=td.GaussianPulse(freq0=193.4e12, fwidth=20e12), # 1550nm frequency window
    polarization="Ey"
)

# 3. Create the 2D visual plane camera to record real-time field maps
visual_monitor = td.FieldMonitor(
    center=(0, 0, 0),
    size=(td.inf, td.inf, 0), # Flat slice cutting through the X and Y plane
    freqs=[193.4e12],
    name="realtime_wave_profile"
)

# 4. Compile everything into the Tidy3D Simulation object
sim = td.Simulation(
    size=domain_size,
    grid_spec=td.GridSpec.auto(wavelength=1.55), # Automatically sets up mesh density
    structures=[physical_grid_wire],
    sources=[wave_source],
    monitors=[visual_monitor],
    run_time=1e-12 # Run simulation for 1 picosecond of real-world physical time
)

print("Step-by-step physical environment compiled successfully!")

wavelength = 1.55 # 1550 nanometers
freq0 = td.C_0 / wavelength
fwidth = freq0 / 10.0

# Place the light source at the left edge of your channel
source = td.ModeSource(
    center=(-5.5, 0, 0), # Moved slightly inside the domain from -6
    size=(0, 2, 1), # A vertical plane slicing across the channel width
    source_time=td.ContinuousWave(freq0=freq0, fwidth=fwidth), # Continuous EM wave stream
    direction="+", # Corrected from '+ ' to '+'
    mode_spec=td.ModeSpec(num_modes=1),
    mode_index=0,
    name="input_source" # Added a name for clarity
)

# Create the 2D monitor plane along the X-Y axis at Z=0 (the absolute center of the chip layer)
field_monitor = td.FieldMonitor(
    center=(0, 0, 0),
    size=(td.inf, td.inf, 0), # Captures the whole surface area
    freqs=[freq0],
    name="em_wave_profile"
)

# Re-create the simulation with the new source and monitor
sim = td.Simulation(
    size=domain_size,
    grid_spec=td.GridSpec.auto(wavelength=1.55),
    structures=[physical_grid_wire],
    sources=[source],
    monitors=[field_monitor],
    run_time=1e-12
)
print("Simulation sources and monitors updated with the new ModeSource and FieldMonitor.")

