import klayout.db as db

# 1. Load your GDSII file into the layout engine
layout = db.Layout()
layout.read("/content/infiniminta_omninexus_total (3).gds")

# 2. Select the top cell architecture
top_cell = layout.top_cell()
print(f"Loaded Cell: {top_cell.name}")

# 3. Target the specific layer you want to check (e.g., Layer 1, Datatype 0)
# This usually represents your core grid routing paths
target_layer = layout.layer(1, 0)
shapes = top_cell.shapes(target_layer)

# 4. Create a Region object to perform geometric checks
region = db.Region(shapes)

# --- THE DESIGN RULE CHECKS ---

# Rule A: Minimum Width Check (e.g., ensuring paths aren't narrower than 200nm)
# Note: KLayout measures in micrometers, so 0.2 = 200nm
min_width = 0.2
width_violations = region.width_check(min_width)

# Rule B: Minimum Spacing Check (e.g., ensuring parallel lines are at least 250nm apart)
min_spacing = 0.25
spacing_violations = region.space_check(min_spacing)

# 5. Output the verification results
print("\n--- DRC Scan Results ---")
if width_violations.is_empty():
    print("✅ Width Check Passed: No elements are too narrow.")
else:
    print(f"❌ Width Violations Found: {width_violations.size()} shapes are breaking the limit.")

if spacing_violations.is_empty():
    print("✅ Spacing Check Passed: Clearances are safe.")
else:
    print(f"❌ Spacing Violations Found: {spacing_violations.size()} nodes are bleeding together.")

import klayout.db as db

layout = db.Layout()
layout.dbu = 0.001 # 1nm grid precision

# Instantiate the main processing engine cell
top_cell = layout.create_cell("OMNINEXUS_ROUTING_ENGINE")

# Layer Definitions
LAYER_NULL_INPUT = layout.layer(1, 0)   # Primary ingestion paths
LAYER_GREY_MUX   = layout.layer(2, 0)   # High-density phase channels
LAYER_PSEUDO_DECOY = layout.layer(3, 0) # Security mesh

# 1. Scripting the Null Zone Ingestion Buffer (Parallel Input Bus)
input_lanes = 16
lane_width = 400   # 400nm wide physical wires
lane_spacing = 600 # 600nm clearance to prevent cross-talk

for i in range(input_lanes):
    y_offset = i * (lane_width + lane_spacing)
    # Draw an ingestion path from the edge of the chip to the interface boundary
    input_box = db.Box(0, y_offset, 5000, y_offset + lane_width) # 5 microns long
    top_cell.shapes(LAYER_NULL_INPUT).insert(input_box)

# 2. Scripting the Grey Zone Interface (The Dense Multiplexer Junction)
# Here, we taper the lines down or bring them closer together to maximize space
for i in range(input_lanes):
    y_offset = i * (lane_width + lane_spacing)
    # The Grey Zone compresses the spacing down to 300nm to pack the data tightly
    compressed_y = i * (lane_width + 300)

    # Transition path linking Null Zone to Grey Zone
    grey_box = db.Box(5000, compressed_y, 10000, compressed_y + lane_width)
    top_cell.shapes(LAYER_GREY_MUX).insert(grey_box)

# Export the updated unified layout
layout.write("omninexus_optimized_routing.gds")
print("Successfully compiled the Null-to-Grey optimized routing architecture.")

