import klayout.db as db

layout = db.Layout()
layout.dbu = 0.001 # 1nm grid precision
top_cell = layout.create_cell("CYTOPLASM_SECURITY_GATEWAY")

# Define separate physical layers for the firewall and the digestion zone
LAYER_FIREWALL_WALL = layout.layer(1, 0)   # The protective perimeter ring
LAYER_CYTOPLASM_GATE = layout.layer(2, 0)  # The active switches controlled by the AI
LAYER_NULL_DIGESTER = layout.layer(3, 0)   # The isolated sandbox registers

# 1. Draw the protective Firewall perimeter path
firewall_bus = db.Box(0, 0, 10000, 500) # 10µm defensive bus line
top_cell.shapes(LAYER_FIREWALL_WALL).insert(firewall_bus)

# 2. Script the Cytoplasm Gate Junctions (The Snatch Ports)
# These are routing fingers that run perpendicular, ready to drop traffic down
gate_ports = 4
for i in range(gate_ports):
    x_pos = 2000 + (i * 2000)
    # This gate connects the firewall directly down into the digester floor
    gate_finger = db.Box(x_pos, -1000, x_pos + 400, 0)
    top_cell.shapes(LAYER_CYTOPLASM_GATE).insert(gate_finger)

# 3. Script the Null Zone Digestion Sandboxes (The Containment Floor)
for i in range(gate_ports):
    x_pos = 2000 + (i * 2000)
    # Massive, heavily shielded ground blocks to absorb and analyze the attack payload
    digester_tank = db.Box(x_pos - 400, -3000, x_pos + 800, -1000)
    top_cell.shapes(LAYER_NULL_DIGESTER).insert(digester_tank)

layout.write("cytoplasm_security_gateway.gds")
print("Compiled Cytoplasm Gate architecture successfully.")

