import gdspy
import numpy as np
from google.colab import files
import os

# 1. Initialize a new GDSII library and create a top-level cell for the combined layout
gdspy.current_library.cells.clear()
lib = gdspy.GdsLibrary()
top_cell = lib.new_cell('OMNINEXUS_INTEGRATED_SECURITY', overwrite_duplicate=True)

# 2. Load the Infiniminta Null State GDSII file
null_state_lib = gdspy.GdsLibrary(infile='/content/infiniminta_null_state.gds')
null_state_cell = null_state_lib.cells['INFINIMINTA_NULL_STATE']

# Get its bounding box for positioning
null_state_bbox = null_state_cell.get_bounding_box()

# 3. Load the Cytoplasm Security Gateway GDSII file
gateway_lib = gdspy.GdsLibrary(infile='/content/cytoplasm_security_gateway.gds')
gateway_cell = gateway_lib.cells['CYTOPLASM_SECURITY_GATEWAY']

# Get its bounding box (unscaled) for reference
gateway_bbox_unscaled = gateway_cell.get_bounding_box()

# 4. Add the Infiniminta Null State cell to the top-level cell (at origin)
top_cell.add(gdspy.CellReference(null_state_cell, origin=(0, 0)))

# 5. Calculate position and add the Cytoplasm Security Gateway cell
# We'll magnify the gateway cell to make it more visible and proportionally sized
mag_factor = 10  # Magnify by 10x (10um instead of 1um for firewall_bus)

# Calculate the scaled bounding box of the gateway for accurate positioning
scaled_gateway_width = (gateway_bbox_unscaled[1][0] - gateway_bbox_unscaled[0][0]) * mag_factor
scaled_gateway_height = (gateway_bbox_unscaled[1][1] - gateway_bbox_unscaled[0][1]) * mag_factor

# Place the gateway cell to the right of the null_state_cell with a 20 micron gap
gateway_ref_x = null_state_bbox[1][0] + 20
# Vertically center the gateway relative to the null_state_cell
gateway_ref_y = null_state_bbox[0][1] + (null_state_bbox[1][1] - null_state_bbox[0][1]) / 2 - scaled_gateway_height / 2

top_cell.add(gdspy.CellReference(gateway_cell, origin=(gateway_ref_x, gateway_ref_y), magnification=mag_factor))

# 6. Add conceptual interaction paths (e.g., for detected threats routing)
# These paths represent threats being detected by the Infiniminta chip and sent
# to the Cytoplasm Security Gateway for digestion.

# Define points for the path:
# Exit point from Infiniminta Null State (e.g., near its right edge, middle height)
null_exit_point = (null_state_bbox[1][0] - 5, null_state_bbox[0][1] + (null_state_bbox[1][1] - null_state_bbox[0][1]) / 2)

# Entry point into the scaled Cytoplasm Security Gateway (e.g., to its 'firewall_bus' or 'gate_fingers')
# The original firewall_bus goes from y=0 to y=0.5 (scaled by 10 -> y=0 to y=5 relative to gateway origin)
# A gate_finger example in gateway_cell: x_pos=2000 (2um), y=-1000 (scaled -> x=20, y=-10 relative)

# Let's target one of the Cytoplasm Gate Junctions (LAYER 2 of gateway)
# The first gate junction is at approx x=2um (unscaled) from gateway origin. So, x=20um (scaled).
# The top of the gate junction is at y=0um (unscaled). So, y=0um (scaled).

gateway_entry_x_relative = 20  # 20um from scaled gateway's origin
gateway_entry_y_relative = -5   # Adjusted to be within the gate finger's y-range (0 to -10 scaled)

# Absolute entry point in the top_cell
gateway_entry_point = (gateway_ref_x + gateway_entry_x_relative, gateway_ref_y + gateway_entry_y_relative)

# Create a path (e.g., on Layer 99 for visualization of interaction)
path_width = 2.0  # Visible width for the connection path
interaction_path = gdspy.Path(path_width, null_exit_point)
# First segment is horizontal, so the Y-coordinate of the end point is still null_exit_point[1]
interaction_path.segment(gateway_entry_point[0] - null_exit_point[0] - 5, 0, layer=99) # Horizontal segment towards gateway
# Second segment is vertical. Its length is the difference between target Y and current Y (which is null_exit_point[1])
interaction_path.segment(gateway_entry_point[1] - null_exit_point[1], np.pi / 2, layer=99) # Vertical segment
interaction_path.segment(5, 0, layer=99) # Final segment into the gateway

top_cell.add(interaction_path)

# 7. Save the combined GDSII file
file_name = 'omninexus_integrated_security.gds'
lib.write_gds(file_name)

print(f"[SUCCESS] Combined GDSII file '{file_name}' created successfully.")

# 8. Download the file
if os.path.exists(file_name):
    files.download(file_name)
    print(f"Successfully downloaded '{file_name}'.")
else:
    print(f"[ERROR] File '{file_name}' was NOT found after writing.")

