"""### Compile Omninexus GDSII Layout

This cell defines a function `compile_omninexus_gds_v2()` that generates a GDSII layout for the Infiniminta Omninexus chip. It includes various sub-cells representing different functional zones like the Null Zone (ingestion), Light Zone (optical data), Grey Zone (storage), and Pseudo Realm (security containment). The layout uses specific layers for substrate, shred fins, copper routing, waveguides, AI splitters, XOR gates, storage cells, decoy buses, isolation trenches, and siphon drain vias.
"""

import klayout.db as db
import numpy as np # Import numpy for advanced geometry calculations
import os # Import os to check for file existence

def compile_omninexus_gds_v2():
    # 1. Initialize Layout and Unit Resolution (1nm)
    layout = db.Layout()
    layout.dbu = 0.001

    # Create the Top-Level Cell Container
    master_cell = layout.create_cell("INFINIMINTA_OMNINEXUS_TOTAL")

    # 2. Map Architectural Sub-Layers (Explicitly using Datatype 0)
    # Existing Layers:
    L1_NULL_SUBSTRATE     = layout.layer(1, 0)   # Active silicon base plane
    L2_NULL_SHRED_FINS    = layout.layer(2, 0)   # Clean physical vertical fins
    L3_NULL_COPPER_ROUT   = layout.layer(3, 0)   # Metal interconnection paths

    L4_LIGHT_WAVEGUIDE    = layout.layer(4, 0)   # Optical data lane
    L5_LIGHT_AI_SPLITTER  = layout.layer(5, 0)   # Signal tap engine

    L6_GREY_XOR_GATES     = layout.layer(6, 0)   # Hardwired routing cells
    L7_GREY_STORAGE_CELLS = layout.layer(7, 0)   # Memory register block

    # L10_DECOY_BUS_HORIZ, L11_ISOLATION_TRENCH, L12_SIPHON_DRAIN_VIAS are now defined by the imported Pseudo Dimension Gds.gds

    # NEW LAYERS FOR PHOTONIC FIREWALL (Cytoplasmic/Polymorphic)
    L17_ADAPTIVE_RULE_MATRIX = layout.layer(17, 0) # Polymorphic core
    L20_FIREWALL_STATIC_WALL = layout.layer(20, 0) # Static perimeter
    L21_FIREWALL_DYNAMIC_GATES = layout.layer(21, 0) # Dynamic elements, cytoplasmic routes

    # NEW LAYERS FOR LEX AI HOUSING
    L24_LEX_AI_CORE_ENGINE = layout.layer(24, 0) # Main Lex AI core processing
    L25_LEX_AI_DATA_BUS    = layout.layer(25, 0) # High-speed data bus for Lex AI

    # NEW LAYERS FOR LEX AI ANOMALY REROUTING ZONE (THE TRAP BOX)
    L26_LEX_TRAP_BOX_PERIMETER = layout.layer(26, 0) # Perimeter of the trap box
    L27_LEX_TRAP_BOX_ANOMALY_STORAGE = layout.layer(27, 0) # Area for contained anomalies
    L99_CONCEPTUAL_REROUTE_PATH = layout.layer(99, 0) # Conceptual rerouting path

    # 3. Create Component Sub-Cells (pseudo_cell will be loaded from file)
    null_cell   = layout.create_cell("NULL_ZONE_INGESTION")
    light_cell  = layout.create_cell("LIGHT_ZONE_HIGHWAY")
    grey_cell   = layout.create_cell("GREY_ZONE_VAULT")
    firewall_cell = layout.create_cell("PHOTONIC_FIREWALL_ADAPTIVE")
    lexai_cell = layout.create_cell("LEX_AI_CORE")
    lex_trap_cell = layout.create_cell("LEX_AI_TRAP_BOX") # New cell for the trap box

    # --- LOAD PSEUDO REALM CONTAINMENT FROM GDS FILE --- (Pseudo Dimension as a Layer)
    pseudo_gds_file = "Pseudo Dimension Gds.gds"
    pseudo_top_cell_name = "OMNINEXUS_TOTAL_HARDWARE" # This is the top cell name in Pseudo Dimension Gds.gds
    pseudo_cell_obj = None

    if os.path.exists(pseudo_gds_file):
        # Temporarily read the pseudo_gds_file into a separate layout object
        temp_pseudo_layout = db.Layout()
        temp_pseudo_layout.dbu = 0.001
        temp_pseudo_layout.read(pseudo_gds_file)

        # Find the top cell within this temporary layout
        if temp_pseudo_layout.has_cell(pseudo_top_cell_name):
            pseudo_cell_in_temp_layout = temp_pseudo_layout.cell_by_name(pseudo_top_cell_name)
            # Copy the cell from the temporary layout into the main layout. This makes it part of the hierarchy.
            pseudo_cell_obj = layout.insert_cell(pseudo_cell_in_temp_layout)
            print(f"[*] Successfully loaded '{pseudo_top_cell_name}' from '{pseudo_gds_file}'.")
        else:
            print(f"[ERROR] Top cell '{pseudo_top_cell_name}' not found in '{pseudo_gds_file}'.")
    else:
        print(f"[ERROR] '{pseudo_gds_file}' not found. Pseudo Realm will not be included.")

    # 4. Generate Solid Silicon Topography Geometry

    # NULL ZONE (Layers 1, 2, 3)
    # Base Substrate (Layer 1)
    null_cell.shapes(L1_NULL_SUBSTRATE).insert(db.Box(-15000, -5000, 5000, 5000))

    # 5 Parallel Ingestion Pillars/Fins (Layer 2)
    fin_width = 600
    fin_height = 8000
    spacing = 1200
    start_x = -14000

    for i in range(5):
        x1 = start_x + (i * (fin_width + spacing))
        y1 = -4000
        x2 = x1 + fin_width
        y2 = y1 + fin_height
        null_cell.shapes(L2_NULL_SHRED_FINS).insert(db.Box(x1, y1, x2, y2))

    # Output Routing (Layer 3)
    null_cell.shapes(L3_NULL_COPPER_ROUT).insert(db.Box(4000, -1000, 5000, 1000))


    # LIGHT ZONE (Layers 4 & 5)
    light_cell.shapes(L4_LIGHT_WAVEGUIDE).insert(db.Box(-5000, -1000, 5000, 1000))
    light_cell.shapes(L5_LIGHT_AI_SPLITTER).insert(db.Box(0, 1000, 1000, 4000))


    # GREY ZONE (Layers 6 & 7)
    grey_cell.shapes(L6_GREY_XOR_GATES).insert(db.Box(-5000, -5000, 5000, 5000))
    for row in range(4):
        for col in range(4):
            rx1 = -4000 + (col * 2200)
            ry1 = -4000 + (row * 2200)
            rx2 = rx1 + 1400
            ry2 = ry1 + 1400
            grey_cell.shapes(L7_GREY_STORAGE_CELLS).insert(db.Box(rx1, ry1, rx2, ry2))


    # PHOTONIC FIREWALL (Cytoplasmic/Polymorphic) (Layers 17, 20, 21)
    firewall_size = 10000 # 10um square
    wall_thickness_fw = 500 # 500nm
    gate_count_fw = 10
    gate_width_fw = 300 # 300nm
    gate_spacing_fw = 700 # 700nm

    # Static Outer Wall (Layer 20)
    static_outer_box = db.Box(0, 0, firewall_size, firewall_size)
    static_inner_box = db.Box(wall_thickness_fw, wall_thickness_fw, firewall_size - wall_thickness_fw, firewall_size - wall_thickness_fw)
    hollow_wall_region = db.Region(static_outer_box) - db.Region(static_inner_box)
    firewall_cell.shapes(L20_FIREWALL_STATIC_WALL).insert(hollow_wall_region)

    # Dynamic Internal Gates (Layer 21) - Polymorphic elements and Cytoplasmic routes
    start_pos_fw = -((gate_count_fw / 2) * (gate_width_fw + gate_spacing_fw))
    for i in range(gate_count_fw):
        offset_fw = start_pos_fw + i * (gate_width_fw + gate_spacing_fw)
        # Vertical dynamic gates
        v_gate = db.Box(offset_fw + firewall_size/2, wall_thickness_fw + 200, offset_fw + gate_width_fw + firewall_size/2, firewall_size - wall_thickness_fw - 200)
        firewall_cell.shapes(L21_FIREWALL_DYNAMIC_GATES).insert(v_gate)
        # Horizontal dynamic gates
        h_gate = db.Box(wall_thickness_fw + 200, offset_fw + firewall_size/2, firewall_size - wall_thickness_fw - 200, offset_fw + gate_width_fw + firewall_size/2)
        firewall_cell.shapes(L21_FIREWALL_DYNAMIC_GATES).insert(h_gate)

    # Adaptive Rule Matrix (Layer 17) - Representing the polymorphic salt
    # Creating a pattern of small, irregularly placed crosses to represent the adaptive rule matrix
    for i in range(15):
        cx = np.random.uniform(firewall_size * 0.1, firewall_size * 0.9)
        cy = np.random.uniform(firewall_size * 0.1, firewall_size * 0.9)
        cross_size = 200
        firewall_cell.shapes(L17_ADAPTIVE_RULE_MATRIX).insert(db.Box(cx - cross_size/2, cy - 20, cx + cross_size/2, cy + 20))
        firewall_cell.shapes(L17_ADAPTIVE_RULE_MATRIX).insert(db.Box(cx - 20, cy - cross_size/2, cx + 20, cy + cross_size/2))

    # LEX AI CORE HOUSING (Layers 24, 25)
    lexai_core_size = 8000 # 8um square core
    lexai_bus_width = 300 # 300nm
    lexai_bus_spacing = 600 # 600nm

    # Main Lex AI Core Engine (Layer 24)
    lexai_cell.shapes(L24_LEX_AI_CORE_ENGINE).insert(db.Box(0, 0, lexai_core_size, lexai_core_size))

    # Lex AI Data Bus (Layer 25) - High-speed data connections
    for i in range(5):
        offset = lexai_core_size + 1000 + i * (lexai_bus_width + lexai_bus_spacing) # Offset outside the core
        # Horizontal buses
        lexai_cell.shapes(L25_LEX_AI_DATA_BUS).insert(db.Box(-1000, offset, lexai_core_size + 1000, offset + lexai_bus_width))
        # Vertical buses
        lexai_cell.shapes(L25_LEX_AI_DATA_BUS).insert(db.Box(offset, -1000, offset + lexai_bus_width, lexai_core_size + 1000))

    # LEX AI ANOMALY REROUTING ZONE (THE TRAP BOX) (Layers 26, 27)
    trap_box_size = 6000 # 6um square
    trap_box_perimeter_thickness = 400 # 400nm

    # Trap Box Perimeter (Layer 26)
    trap_outer_box = db.Box(0, 0, trap_box_size, trap_box_size)
    trap_inner_box = db.Box(trap_box_perimeter_thickness, trap_box_perimeter_thickness, trap_box_size - trap_box_perimeter_thickness, trap_box_size - trap_box_perimeter_thickness)
    trap_perimeter_region = db.Region(trap_outer_box) - db.Region(trap_inner_box)
    lex_trap_cell.shapes(L26_LEX_TRAP_BOX_PERIMETER).insert(trap_perimeter_region)

    # Anomaly Storage Area (Layer 27) - Representing the

compile_omninexus_gds_v2()

