import gdspy
import numpy as np
from google.colab import files

gdspy.current_library.cells.clear()

lib = gdspy.GdsLibrary()
cell = lib.new_cell('INFINIMINTA_GREY_INTERFACE')

# --- CONFIGURATION ---
pitch = 0.6
hex_radius = 0.28 # Define hex_radius for use in the polygon creation
rows, cols = 60, 60

# --- LAYER 1: THE LIGHT (Top Processor) ---
for r in range(rows):
    for c in range(cols):
        x, y = c * pitch * 1.5, r * pitch * np.sqrt(3)
        if c % 2 == 1: y += (pitch * np.sqrt(3)) / 2

        # Manually calculate vertices for a regular hexagon
        points = []
        for i in range(6):
            angle = np.deg2rad(i * 60) # 60 degrees per segment for a hexagon
            px = x + hex_radius * np.cos(angle)
            py = y + hex_radius * np.sin(angle)
            points.append((px, py))
        hexagon = gdspy.Polygon(points, layer=1)
        cell.add(hexagon)

# --- LAYER 2: THE GREY ZONE (Ghost Interface) ---
# In KLayout, these will appear as 'Interconnects'
# This is where data is flattened and stored.
for r in range(0, rows, 2):
    for c in range(0, cols, 2):
        x, y = c * pitch * 1.5, r * pitch * np.sqrt(3)
        if c % 2 == 1: y += (pitch * np.sqrt(3)) / 2
        # Ghost Pillars: Connecting Light to Null
        ghost_pillar = gdspy.Round((x, y), 0.15, layer=2)
        cell.add(ghost_pillar)

# --- LAYER 5: THE NULL (The Abyss Floor) ---
# A solid block of 'Optical Black' material
null_floor = gdspy.Rectangle((-10, -10), (cols*pitch*1.5+10, rows*pitch*np.sqrt(3)+10), layer=5)
cell.add(null_floor)

# --- LAYER 8: PREDATOR NEEDLES (Retaliation Ports) ---
def add_needle(pos, angle):
    n = gdspy.Polygon([(0, -2), (25, -0.05), (25, 0.05), (0, 2)], layer=8)
    n.rotate(angle).translate(pos[0], pos[1])
    cell.add(n)

cx, cy = (cols*pitch*1.5)/2, (rows*pitch*np.sqrt(3))/2
add_needle((cols*pitch*1.5 + 5, cy), 0) # Predator Port East

# Export
lib.write_gds('infiniminta_grey_zone.gds')
files.download('infiniminta_grey_zone.gds')

