lex_ai_instance = photon_sim.lex_ai

class AdaptiveDigitalFirewall:
    def __init__(self, lex_ai_instance, initial_rules=None):
        self.lex_ai = lex_ai_instance
        self.firewall_rules = initial_rules if initial_rules is not None else ["ALLOW_ALL"]
        self.update_frequency_hz = 10e6 # 10 MHz as stated previously
        self.packet_log = []
        self.threat_history = []
        print("🛡️ [AdaptiveDigitalFirewall] Initialized. Operating under LexAI supervision.")
        self.lex_ai.update_firewall_rules(self.firewall_rules)

    def _generate_dynamic_rule(self):
        """Simulates generating a new dynamic firewall rule."""
        rule_types = ["DENY_IP", "ALLOW_PORT", "BLOCK_PATTERN"]
        new_rule = f"{random.choice(rule_types)}_{random.randint(1, 255)}.{random.randint(0,255)}.{random.randint(0,255)}.{random.randint(0,255)}"
        if len(self.firewall_rules) > 5:
            # Keep the rule set manageable for visualization
            self.firewall_rules.pop(0)
        self.firewall_rules.append(new_rule)
        return new_rule

    def process_packet(self, packet_id, source_ip, destination_port, payload):
        """Simulates processing an incoming packet."""
        # Dynamic rule update at 10 MHz is too fast for simulation, so we'll update periodically
        # For this 5-second simulation, we'll update more visually often.
        if random.random() < 0.2: # Update rules 20% of the time a packet comes in
            new_rule = self._generate_dynamic_rule()
            self.lex_ai.update_firewall_rules(self.firewall_rules) # Notify LexAI of the change

        is_threat = False
        action = "ALLOW"

        # Simple threat detection logic
        if "exploit" in payload.lower() or "malware" in payload.lower():
            is_threat = True
            action = "DENY"
            self.lex_ai.report_threat({"packet_id": packet_id, "source_ip": source_ip, "payload": payload})
            self.threat_history.append((time.time(), packet_id, source_ip, payload))

        self.packet_log.append({
            "time": time.time(),
            "packet_id": packet_id,
            "source_ip": source_ip,
            "destination_port": destination_port,
            "payload": payload,
            "action": action,
            "is_threat": is_threat,
            "current_rules": list(self.firewall_rules)
        })
        return action, is_threat

# --- Initialization of LexAI and AdaptiveDigitalFirewall ---
