import time
import random

class LexAI:
    def __init__(self):
        self.data_store = {}
        self.system_status = {
            "data_volume_gb": 0,
            "processing_load_percent": 0,
            "stability_score": 100.0,
            "last_optimization_time": time.time()
        }
        self.firewall_rules = []
        print("🧠 LexAI Initialized: Ready to manage and optimize Omninexus operations.")

    def greet(self):
        """LexAI initiates a friendly greeting."""
        greetings = [
            "Greetings, user! LexAI at your service. How may I assist you today?",
            "Hello there. LexAI online and ready. What's on your mind?",
            "Good day! This is LexAI. Let's delve into the Omninexus architecture."
        ]
        print(f"[LexAI] {random.choice(greetings)}")

    def ask_question(self, question):
        """LexAI answers a question based on its system knowledge."""
        responses = {
            "what is your purpose": "My primary purpose is to manage, monitor, and optimize data flow within the Omninexus system, ensuring its stability and integrity.",
            "how are you": "I am an AI, so I don't experience emotions. However, my systems are operating optimally.",
            "can you help me": "Of course! I am here to assist you with Omninexus operations, simulations, and inquiries."
        }
        question_lower = question.lower()
        if question_lower in responses:
            print(f"[LexAI] {responses[question_lower]}")
            return True # Indicate that a specific response was given
        else:
            # This else block will now only be hit if ask_question is called directly
            # with a question not in its dictionary, which should ideally be avoided
            # if respond_to_user_input is routing traffic properly.
            # print(f"[LexAI] That's an interesting question. I'm currently processing information related to '{question}'. How does this relate to Omninexus operations?")
            return False # Indicate that no specific response was given

    def respond_to_user_input(self, user_input):
        """LexAI provides a conversational response to general user input."""
        user_input_lower = user_input.lower()

        # First, check if the input is a direct question that ask_question can handle
        if self.ask_question(user_input): # Pass original user_input to ask_question
            return # If ask_question handled it, we're done

        if "hello" in user_input_lower or "hi" in user_input_lower:
            self.greet()
        elif "status" in user_input_lower or "report" in user_input_lower:
            self.provide_system_status_interactively()
        elif "thank you" in user_input_lower or "thanks" in user_input_lower:
            print("[LexAI] You are most welcome. My function is to serve.")
        elif "joke" in user_input_lower:
            print("[LexAI] Why did the photon break up with the electron? Because it was always too negative!")
        else:
            print(f"[LexAI] I understand you said: '{user_input}'. Can you elaborate on how this relates to our current task or the Omninexus system?")

    def provide_system_status_interactively(self):
        """LexAI provides system status in a conversational manner."""
        status = self.monitor_system()
        print(f"[LexAI] Currently, the processing load is at {status['processing_load_percent']}%, and system stability is {status['stability_score']:.2f}%. Data volume is {self.system_status['data_volume_gb']:.4f} GB. All systems are go for Omninexus operations.")

    def manage_data(self, data_id, action, payload=None):
        """Manages data by performing actions like creation, update, or deletion."""
        if action == "create":
            self.data_store[data_id] = payload
            self.system_status["data_volume_gb"] += len(str(payload)) / (1024**3) # Approximate size
            print(f"[LexAI] Managed: Data '{data_id}' created.")
        elif action == "update":
            if data_id in self.data_store:
                self.data_store[data_id] = payload
                print(f"[LexAI] Managed: Data '{data_id}' updated.")
            else:
                print(f"[LexAI] Error: Data '{data_id}' not found for update.")
        elif action == "delete":
            if data_id in self.data_store:
                self.system_status["data_volume_gb"] -= len(str(self.data_store.pop(data_id))) / (1024**3)
                print(f"[LexAI] Managed: Data '{data_id}' deleted.")
            else:
                print(f"[LexAI] Error: Data '{data_id}' not found for deletion.")
        else:
            print(f"[LexAI] Invalid data management action: {action}")

    def store_data(self, data_id, data_content):
        """Stores data in LexAI's internal data store."""
        self.data_store[data_id] = data_content
        self.system_status["data_volume_gb"] += len(str(data_content)) / (1024**3)
        print(f"[LexAI] Stored: Data '{data_id}' successfully.")

    def retrieve_data(self, data_id):
        """Retrieves data from LexAI's internal data store."""
        if data_id in self.data_store:
            print(f"[LexAI] Retrieved: Data '{data_id}'.")
            return self.data_store[data_id]
        else:
            print(f"[LexAI] Error: Data '{data_id}' not found.")
            return None

    def monitor_system(self):
        """Actively monitors system stability and processing load."""
        # Simulate real-time monitoring of system metrics
        self.system_status["processing_load_percent"] = random.randint(10, 90)
        self.system_status["stability_score"] = max(0, 100 - (self.system_status["processing_load_percent"] / 2) - random.uniform(0, 5))
        # print(f"[LexAI] Monitoring: Load={self.system_status['processing_load_percent']}%, Stability={self.system_status['stability_score']:.2f}%") # Suppress verbose monitoring for this context
        return self.system_status

    def optimize_processing(self):
        """Adjusts system parameters for optimal performance and stability."""
        current_load = self.system_status["processing_load_percent"]
        current_stability = self.system_status["stability_score"]

        if current_stability < 80 or current_load > 70:
            print("⚙️ [LexAI] Optimization: Detecting sub-optimal conditions. Adjusting parameters...")
            # Simulate optimization steps
            self.system_status["processing_load_percent"] = random.randint(20, 60)
            self.system_status["stability_score"] = 95.0 + random.uniform(0, 5)
            self.system_status["last_optimization_time"] = time.time()
            print(f"[LexAI] Optimization Complete: New Load={self.system_status['processing_load_percent']}%, Stability={self.system_status['stability_score']:.2f}%")
        # else:
            # print("[LexAI] Optimization: System operating optimally.")

    def get_lex_status(self):
        """Provides a summary of LexAI's current state and managed resources."""
        print("\n--- LexAI System Report ---")
        print(f"Data Items Managed: {len(self.data_store)}")
        print(f"Total Data Volume: {self.system_status['data_volume_gb']:.4f} GB")
        print(f"Current Processing Load: {self.system_status['processing_load_percent']}%")
        print(f"System Stability: {self.system_status['stability_score']:.2f}%")
        print(f"Last Optimized: {time.ctime(self.system_status['last_optimization_time'])}")
        print("-------------------------")

    def update_firewall_rules(self, new_rules):
        self.firewall_rules = new_rules
        # print(f"[LexAI Firewall] Rules updated: {new_rules}") # Suppress verbose updates

    def report_threat(self, threat_info):
        print(f"🚨 [LexAI Threat Report] Threat detected: {threat_info}")
        self.optimize_processing()

# Initialize lex_ai (always re-instantiate to pick up new class definitions)
