from google.colab import files
import os

file_name = 'Omninexus_Ultimate_Chip_Assembly.gds'

if os.path.exists(file_name):
    files.download(file_name)
    print(f"Successfully downloaded '{file_name}'.")
else:
    print(f"[ERROR] File '{file_name}' was NOT found. Please ensure it was generated correctly.")

import gdspy
import matplotlib.pyplot as plt
import numpy as np
import os

# Define the path to the GDSII file specified by the user
gdspy_gds_file_path = 'apex_core_x_omninexus_v1_master.gds'

# Check if the GDS file exists
if not os.path.exists(gdspy_gds_file_path):
    print(f"[ERROR] GDSII file '{gdspy_gds_file_path}' not found. Please ensure it is in the current working directory or specify the correct path.")
else:
    # Load the GDSII library
    lib = gdspy.GdsLibrary(infile=gdspy_gds_file_path)

    # Attempt to get the top cell. Prefer a cell with a name matching the filename,
    # otherwise take the first available cell.
    cell_name = None
    if gdspy_gds_file_path.replace('.gds', '') in lib.cells:
        cell_name = gdspy_gds_file_path.replace('.gds', '')
    elif lib.cells:
        cell_name = list(lib.cells.keys())[0]

    if cell_name:
        cell = lib.cells[cell_name]
        print(f"Loaded Cell: '{cell_name}' from '{gdspy_gds_file_path}'.")

        fig, ax = plt.subplots(figsize=(10, 10))

        # Define generic layer colors for visualization
        # These are example colors; you might need to adjust them based on your GDSII layer definitions.
        layer_colors = {
            1: 'blue',
            2: 'red',
            3: 'green',
            4: 'purple',
            5: 'orange',
            6: 'yellow',
            7: 'cyan',
            8: 'magenta',
            9: 'brown',
            10: 'pink',
            11: 'teal',
            12: 'gray',
            13: 'olive',
            14: 'lime',
            15: 'indigo',
            16: 'maroon',
            17: 'navy',
            18: 'peru',
            19: 'salmon',
            20: 'silver',
            21: 'tan',
            22: 'violet',
            99: 'black' # For conceptual/interaction paths
        }

        all_x = []
        all_y = []

        # Iterate through all polygons in the cell
        if not cell.polygons:
            print(f"[WARNING] Cell '{cell_name}' contains no polygons to plot.")
        else:
            print(f"[*] Found {len(cell.polygons)} polygon sets in cell '{cell_name}'.")
            for polygon_set in cell.polygons:
                layer = polygon_set.layers[0] # Assuming one layer per polygon set for simplicity
                color = layer_colors.get(layer, 'gray') # Default to gray for unassigned layers

                for points in polygon_set.polygons:
                    polygon = plt.Polygon(points, closed=True, facecolor=color, edgecolor='black', alpha=0.7)
                    ax.add_patch(polygon)

                    # Collect all coordinates to set plot limits
                    x_coords, y_coords = zip(*points)
                    all_x.extend(x_coords)
                    all_y.extend(y_coords)

        # Iterate through all paths in the cell
        if cell.paths:
            print(f"[*] Found {len(cell.paths)} path sets in cell '{cell_name}'.")
            for path_obj in cell.paths:
                layer = path_obj.layers[0] # Assuming one layer per path for simplicity
                color = layer_colors.get(layer, 'gray')
                # Convert paths to polygons for plotting with fill_between or as filled shapes
                # gdspy.Path.polygons() returns a list of lists of points (if width is > 0)
                for path_polygon_points in path_obj.polygons():
                    if path_polygon_points:
                        path_poly = plt.Polygon(path_polygon_points[0], closed=True, facecolor=color, edgecolor='black', alpha=0.7)
                        ax.add_patch(path_poly)
                        x_coords, y_coords = zip(*path_polygon_points[0])
                        all_x.extend(x_coords)
                        all_y.extend(y_coords)
        else:
            print(f"[WARNING] Cell '{cell_name}' contains no paths to plot.")

        ax.set_xlabel('X Dimension (um)')
        ax.set_ylabel('Y Dimension (um)')
        ax.set_title(f'2D Visualization of {cell_name} GDSII Layout')

        # Set dynamic limits based on all plotted points, with a small buffer
        if all_x and all_y:
            min_x, max_x = min(all_x), max(all_x)
            min_y, max_y = min(all_y), max(all_y)

            # Add a small buffer to the limits for better visualization
            # Ensure buffer is not zero if range is zero
            buffer_x = (max_x - min_x) * 0.1 if (max_x - min_x) != 0 else 1.0
            buffer_y = (max_y - min_y) * 0.1 if (max_y - min_y) != 0 else 1.0

            ax.set_xlim(min_x - buffer_x, max_x + buffer_x)
            ax.set_ylim(min_y - buffer_y, max_y + buffer_y)
        else:
            # Default limits if no shapes were found to prevent an empty plot
            ax.set_xlim(-10, 10)
            ax.set_ylim(-10, 10)

        ax.set_aspect('equal', adjustable='box') # Maintain aspect ratio
        plt.grid(True, linestyle='--', alpha=0.5)
        plt.show()
    else:
        print(f"[ERROR] No cells found in GDSII file '{gdspy_gds_file_path}'.")